package com.edureminder.quicktube.core.download

import com.edureminder.quicktube.core.model.SubtitleTrack

/** Captions saved next to a downloaded video, as SubRip (.srt): the format every player reads. */
internal object SubtitleFiles {
    /**
     * The track to save: the video's own captions in the phone's language, then English, then any; auto-generated
     * ones only when there are no others (in the phone's language or English).
     */
    fun pick(tracks: List<SubtitleTrack>, phoneLanguage: String): SubtitleTrack? {
        fun lang(t: SubtitleTrack) = t.language.substringBefore('-').lowercase()
        val wanted = listOf(phoneLanguage.lowercase(), "en")
        val own = tracks.filter { !it.autoGenerated }
        return wanted.firstNotNullOfOrNull { w -> own.firstOrNull { lang(it) == w } } ?: own.firstOrNull()
            ?: wanted.firstNotNullOfOrNull { w -> tracks.firstOrNull { it.autoGenerated && lang(it) == w } }
    }

    /**
     * The tracks to save beside a download (at most [max], one per language): the phone's language and English (the
     * video's own captions first, else auto-generated), then the video's own captions in any other language; a video
     * with only auto-generated captions in other languages still gets its first one.
     */
    fun pickAll(tracks: List<SubtitleTrack>, phoneLanguage: String, max: Int = 3): List<SubtitleTrack> {
        fun lang(t: SubtitleTrack) = t.language.substringBefore('-').lowercase()
        val wanted = listOf(phoneLanguage.lowercase(), "en").distinct()
        val own = tracks.filter { !it.autoGenerated }
        val auto = tracks.filter { it.autoGenerated }
        val ordered = wanted.mapNotNull { w -> own.firstOrNull { lang(it) == w } ?: auto.firstOrNull { lang(it) == w } } + own
        return ordered.distinctBy { lang(it) }.take(max).ifEmpty { listOfNotNull(auto.firstOrNull()) }
    }

    /** "Title(720p).mp4" + "en" → "Title(720p).en.srt" (players pick it up by name, language tag included). */
    fun nameFor(videoName: String, language: String): String =
        videoName.substringBeforeLast('.') + "." + language.replace(Regex("[^A-Za-z0-9-]"), "") + ".srt"

    private val timing = Regex("""^\s*((?:\d+:)?\d{1,2}:\d{2}\.\d{3})\s+-->\s+((?:\d+:)?\d{1,2}:\d{2}\.\d{3})""")
    private val tags = Regex("""<[^>]*>""")

    /**
     * WebVTT → SubRip. Styling and inline timestamps are dropped, and YouTube's auto-generated captions (which repeat
     * the previous line in every cue and add 10 ms filler cues) become one clean line per cue.
     */
    fun vttToSrt(vtt: String): String {
        data class Cue(val start: Long, val end: Long, val lines: List<String>)
        val cues = mutableListOf<Cue>()
        val blocks = vtt.replace("\r\n", "\n").split(Regex("""\n\s*\n"""))
        for (block in blocks) {
            val lines = block.lines()
            val t = lines.indexOfFirst { timing.containsMatchIn(it) }
            if (t < 0) continue
            val m = timing.find(lines[t])!!
            val text = lines.drop(t + 1).map { decode(it.replace(tags, "")).trim() }.filter { it.isNotEmpty() }
            if (text.isEmpty()) continue
            cues += Cue(ms(m.groupValues[1]), ms(m.groupValues[2]), text)
        }
        val out = StringBuilder()
        var n = 0
        var previous: List<String> = emptyList()
        for (c in cues) {
            if (c.end - c.start < 50) { previous = c.lines; continue }
            // Rolling captions: a cue starting with the last cue's text only adds its new line.
            val fresh = c.lines.dropWhile { it in previous }.ifEmpty { if (c.lines == previous) emptyList() else c.lines }
            previous = c.lines
            if (fresh.isEmpty()) continue
            out.append(++n).append('\n').append(srtTime(c.start)).append(" --> ").append(srtTime(c.end)).append('\n')
            fresh.forEach { out.append(it).append('\n') }
            out.append('\n')
        }
        return out.toString()
    }

    private fun ms(t: String): Long {
        val parts = t.split(':')
        val (h, m, s) = if (parts.size == 3) Triple(parts[0].toLong(), parts[1].toLong(), parts[2]) else Triple(0L, parts[0].toLong(), parts[1])
        val (sec, milli) = s.split('.').let { it[0].toLong() to it[1].toLong() }
        return ((h * 60 + m) * 60 + sec) * 1000 + milli
    }

    private fun srtTime(ms: Long) = "%02d:%02d:%02d,%03d".format(ms / 3_600_000, ms / 60_000 % 60, ms / 1000 % 60, ms % 1000)

    private fun decode(s: String) = s.replace("&amp;", "&").replace("&lt;", "<").replace("&gt;", ">").replace("&quot;", "\"")
        .replace("&#39;", "'").replace("&nbsp;", " ")
}
